parameters.jsCode:
const raw = $input.item.json.output;
let parsed = null;

if (raw !== null && raw !== undefined) {
  let text = typeof raw === 'string' ? raw : JSON.stringify(raw);
  const fence = String.fromCharCode(96, 96, 96);
  text = text.split(fence).join('').trim();
  if (text.toLowerCase().indexOf('json') === 0) text = text.slice(4).trim();
  const match = text.match(/\{[\s\S]*\}/);
  if (match) text = match[0];
  try { parsed = JSON.parse(text); } catch (e) { parsed = null; }
}

let lead = {};
try {
  lead = $('Verify Email (Code)1').item.json || {};
} catch (e) {
  lead = {};
}

let score = null;
let reasoning = '';

if (parsed && typeof parsed === 'object') {
  let s = parsed.score;
  if (typeof s === 'string') s = parseFloat(s.replace(/[^0-9.\-]/g, ''));
  if (typeof s === 'number' && !Number.isNaN(s)) {
    score = Math.max(0, Math.min(10, s));
    reasoning = parsed.reasoning || 'No reasoning provided';
  }
}

if (score === null) {
  // AI scoring unavailable (rate limit / error / bad output): fall back to seniority + title so good leads are not lost.
  const sen = String(lead.seniority || '').toLowerCase();
  const title = String(lead.title || '').toLowerCase();
  if (sen === 'c_suite' || sen === 'owner' || sen === 'founder' || sen === 'partner' || /\b(ceo|coo|cfo|cto|cmo|chief|founder|owner|president)\b/.test(title)) {
    score = 9;
  } else if (sen === 'vp' || /\b(vp|vice president)\b/.test(title)) {
    score = 8;
  } else if (sen === 'director' || /\b(director|head)\b/.test(title)) {
    score = 7;
  } else {
    score = 5;
  }
  reasoning = 'AI scoring unavailable - scored from seniority/title instead';
}

return {
  json: {
    ...lead,
    icp_score: score,
    icp_reasoning: reasoning
  }
};

const j = $json || {};
const score = Number(j.icp_score ?? 0);
const reasoning = j.icp_reasoning || '';
const titleCase = (s) => {
  const t = String(s == null ? '' : s).trim();
  return t && t === t.toLowerCase() ? t.replace(/\b([a-z])/g, (m) => m.toUpperCase()) : t;
};

const fullName = `${j.firstName || ''} ${j.lastName || ''}`.trim();

const domain = (j.companyDomain || '')
  .toString()
  .replace(/^https?:\/\//i, '')
  .replace(/^www\./i, '')
  .replace(/\/.*$/, '');

const phone = (j.phone || '').toString().split(/[,;]/)[0].trim();

const industry = Array.isArray(j.companyIndustry)
  ? j.companyIndustry.join(', ')
  : (j.companyIndustry || '');

const email = (j.email || j.email_address || '')
  .toString()
  .trim()
  .toLowerCase();

// Company name: fall back to the web domain when the source data is empty.
let company = String(j.companyName || '').trim();
if (!company) {
  const root = domain.split('.')[0] || '';
  company = root ? root.charAt(0).toUpperCase() + root.slice(1) : '';
}

// City: the source sometimes puts the country name in the city field - use the company city instead.
const country = j.personCountry || j.companyCountry || '';
let city = String(j.personCity || '').trim();
if (!city || city.toLowerCase() === String(country).toLowerCase()) {
  city = String(j.companyCity || '').trim();
}

return {
  json: {
    'Full Name': titleCase(fullName),
    'Job Title': titleCase(j.title || ''),
    'Company': titleCase(company),
    'Industry': industry,
    'Company Domain': domain,
    'Company Size': j.companySize != null ? j.companySize : '',
    'Revenue Range': j.annualRevenue != null ? j.annualRevenue : '',
    'Email': email,
    'Phone': phone,
    'City': titleCase(city),
    'Country': country,
    'LinkedIn': j.linkedinUrl || '',
    'Intent Signal Score': Math.round(score * 10),
    icp_score: score,
    icp_reasoning: reasoning,
    email_quality: j.email_quality || '',
    email_quality_reason: j.email_quality_reason || '',
    email_deliverability: j.email_deliverability || { status: 'undeliverable', reason: 'missing_verification' }
  }
};

// Deterministic dedup: (1) against existing CRM rows, (2) within the current batch.
// Primary key = normalized email; fallback = normalized full name + company domain.
const norm = (v) => (v == null ? '' : v.toString().trim().toLowerCase());
const keyFor = (o) => {
  const email = norm(o.Email || o.email);
  if (email) return 'e:' + email;
  const name = norm(o['Full Name']).replace(/\s+/g, ' ');
  const domain = norm(o['Company Domain']);
  if (name || domain) return 'n:' + name + '|' + domain;
  return '';
};

// FAIL-SAFE: if the CRM sheet could not be read, stop. Never risk emailing leads twice.
let existingRows = [];
let readFailed = false;
try { existingRows = $('Check If Lead Already In Sheet1').all().map(i => i.json); } catch (e) { readFailed = true; }
if (readFailed || existingRows.some(r => r && r.error && !r.Email)) {
  throw new Error('Duplicate check failed: could not read the CRM sheet. Stopping so no lead is contacted twice.');
}

const existing = new Set();
for (const r of existingRows) {
  if (r && Object.keys(r).length > 0) {
    const k = keyFor(r);
    if (k) existing.add(k);
  }
}

const leads = $('Normalize Lead').all().map(i => i.json);
const seenInBatch = new Set();
const out = [];
for (const lead of leads) {
  const k = keyFor(lead);
  let isDup = false;
  let reason = '';
  if (!k) {
    isDup = true; reason = 'no_identity_key';
  } else if (existing.has(k)) {
    isDup = true; reason = 'already_in_crm';
  } else if (seenInBatch.has(k)) {
    isDup = true; reason = 'duplicate_in_batch';
  } else {
    seenInBatch.add(k);
  }
  out.push({ json: { ...lead, lead_key: k, is_duplicate: isDup, dedupe_reason: reason, outreach_status: isDup ? 'duplicate' : 'qualified' } });
}
return out;

const lead = $json || {};
const email = String(lead.Email || '').trim().toLowerCase();
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email);
const fullName = String(lead['Full Name'] || '').trim();
const firstName = fullName ? fullName.split(' ')[0] : '';
const company = String(lead.Company || '').trim();
let subject;
if (firstName && company) subject = firstName + ', quick idea for ' + company;
else if (company) subject = 'Quick idea for ' + company;
else if (firstName) subject = firstName + ', a quick idea';
else subject = 'A quick idea for your team';
return { json: {
  ...lead,
  email_norm: email,
  email_valid: emailValid,
  email_subject: subject,
  whatsapp_enabled: true
} };

parameters.text:
=Write a short, natural, non-generic cold outreach EMAIL body (not the subject line) for this lead.

Lead details:
- Name: {{ $json['Full Name'] }}
- Job Title: {{ $json['Job Title'] }}
- Company: {{ $json.Company }}
- Industry: {{ $json.Industry }}
- City/Country: {{ $json.City }}, {{ $json.Country }}
- Intent Signal Score: {{ $json['Intent Signal Score'] }}

Context: We are Triple A, an AI automation agency. We help firms in this lead's industry automate manual operations work (intake, follow-ups, reporting) using AI, usually saving teams 10-20 hours a week without adding headcount.

Requirements:
- Reference their specific job title, company, or industry naturally - do not sound templated
- Keep it under 90 words
- End with a soft ask for a 15-minute call this week
- Sign off as: Best,\nTriple A
- Do not invent facts about the lead or company that were not provided
- Return ONLY the email body text, no subject line, no markdown, no extra commentary

