// Record Gmail submission and classify any immediate SMTP/API error conservatively.
// A successful Gmail response means Gmail accepted the message for sending; it does NOT prove
// final recipient delivery. Final bounces/deferred notices can arrive asynchronously later.
const ctx = $('Prepare Outreach Context').item.json;
const resp = $json || {};
const rawError = resp.error?.message || resp.message || (resp.error ? JSON.stringify(resp.error) : '');
const text = String(rawError).toLowerCase();
const codeMatch = text.match(/\b([245]\d\d)\b/);
const smtpCode = codeMatch ? codeMatch[1] : '';

let deliveryClass = 'submitted_pending_delivery';
let status = 'email_submitted';
if (rawError) {
  if (/\b550\b|5\.1\.1|user unknown|no mailbox|recipient address rejected|mailbox.*not.*available/.test(text)) {
    deliveryClass = 'hard_bounce';
    status = 'email_bounced';
  } else if (/\b452\b|\b450\b|\b451\b|4\.3\.1|servfail|timed out|timeout|temporar|try again|deferred|connection.*failed/.test(text)) {
    deliveryClass = 'temporary_deferred';
    status = 'email_deferred';
  } else if (/\b5\.7\.1\b|\b550\b.*(blocked|spam|policy|authentication)|spf|dkim|dmarc|sender.*reject/.test(text)) {
    deliveryClass = 'sender_or_policy_rejection';
    status = 'email_rejected';
  } else {
    deliveryClass = 'send_error_unknown';
    status = 'email_failed';
  }
}

const messageId = resp.id || resp.messageId || (resp.data && (resp.data.id || resp.data.messageId)) || '';
return { json: {
  ...ctx,
  email_status: status,
  email_delivery_class: deliveryClass,
  email_smtp_code: smtpCode,
  email_message_id: rawError ? '' : messageId,
  email_error: rawError,
  email_sent_at: rawError ? '' : $now.toISO(),
  email_delivery_note: rawError ? 'Immediate send/SMTP response classified; final delivery may still generate a later Gmail bounce notice.' : 'Gmail accepted the message for sending; final recipient delivery is not yet confirmed.'
} };

// Country name -> calling code (used only when the number has no international prefix)
const countryCodes = {
  'lebanon': '961', 'united arab emirates': '971', 'uae': '971', 'saudi arabia': '966', 'qatar': '974', 'jordan': '962',
  'united states': '1', 'usa': '1', 'u.s.a.': '1', 'united states of america': '1', 'canada': '1',
  'united kingdom': '44', 'uk': '44', 'nigeria': '234', 'ghana': '233', 'kenya': '254', 'south africa': '27',
  'india': '91', 'australia': '61', 'ireland': '353', 'germany': '49', 'france': '33'
};

const rawPhone = ($json.Phone || '').toString();
const rawCountry = ($json.Country || '').toString();
const normalizedCountry = rawCountry.trim().toLowerCase().replace(/\s+/g, ' ');
const code = countryCodes[normalizedCountry] || '';

// If several numbers are listed, use the first one.
const first = rawPhone.split(/[,;]/)[0].trim();
const isInternational = first.startsWith('+') || first.startsWith('00');
let digits = first.replace(/\D/g, '');
if (first.startsWith('00')) digits = digits.slice(2);

let cleanedPhone = '';
if (digits) {
  if (isInternational) {
    cleanedPhone = digits;
  } else if (code && digits.indexOf(code) === 0) {
    cleanedPhone = digits;
  } else if (code && digits.indexOf('0') === 0) {
    cleanedPhone = code + digits.replace(/^0+/, '');
  } else if (code) {
    cleanedPhone = code + digits;
  } else {
    cleanedPhone = digits;
  }
}

const isValid = cleanedPhone.length >= 8 && cleanedPhone.length <= 15;
let status;
if (!digits) { status = 'no_phone'; } else if (!isValid) { status = 'invalid_number'; } else { status = 'ok'; }

return {
  json: {
    ...$json,
    cleanedPhone: isValid ? cleanedPhone : '',
    whatsappChatId: isValid ? (cleanedPhone + '@c.us') : '',
    phoneCleanupStatus: status
  }
};

parameters.text:
=Write a short, natural WhatsApp outreach message (not email) for this lead. This is a WhatsApp follow-up, so keep it casual, brief, and conversational - not a formal email tone.

Lead details:
- Name: {{ $('Code in JavaScript').item.json['Full Name'] }}
- Job Title: {{ $('Code in JavaScript').item.json['Job Title'] }}
- Company: {{ $('Code in JavaScript').item.json.Company }}
- Industry: {{ $('Code in JavaScript').item.json.Industry }}
- City/Country: {{ $('Code in JavaScript').item.json.City }}, {{ $('Code in JavaScript').item.json.Country }}

Context: We are Triple A, an AI automation agency. We help firms in this lead's industry automate manual operations work using AI, usually saving teams 10-20 hours a week.

Requirements:
- Under 40 words
