parameters.jsCode:
// Runs whether Green-API succeeded or failed (node set to continue on the regular output).
const ctx = $('Code in JavaScript').item.json;
const resp = $json || {};
const hasError = !!resp.error;
const idMessage = resp.idMessage || (resp.data && resp.data.idMessage) || '';
return {
  json: {
    ...ctx,
    whatsapp_chat_id: ctx.whatsappChatId || '',
    whatsapp_status: hasError ? 'whatsapp_failed' : 'whatsapp_sent',
    whatsapp_message_id: hasError ? '' : idMessage,
    whatsapp_error: hasError ? (resp.error && resp.error.message ? resp.error.message : String(resp.error)) : '',
    whatsapp_sent_at: hasError ? '' : $now.toISO()
  }
};

// Preserve lead context across EVERY outreach branch.
// The branch node's current item is always preferred; fallback sources are used only
// when a branch node returns a service response without the original lead fields.
const current = $json || {};
let base = { ...current };

const hasLead = (o) => !!(o && (o.Email || o['Full Name'] || o.email_norm));
const mergeSource = (sourceName) => {
  try {
    const candidate = $(sourceName).item.json || {};
    if (hasLead(candidate)) base = { ...candidate, ...base };
  } catch (e) {}
};

if (!hasLead(base)) mergeSource('Code in JavaScript');
if (!hasLead(base)) mergeSource('Prepare Outreach Context');
if (!hasLead(base)) mergeSource('Record Email Result');
if (!hasLead(base)) mergeSource('Branch to Email + WhatsApp1');

const emailStatus = base.email_status || '';
const waStatus = base.whatsapp_status || '';
const emailSuccess = ['email_submitted','email_sent'].includes(emailStatus);
const waSuccess = waStatus === 'whatsapp_sent';
const outreach = emailSuccess && waSuccess ? 'completed' : (emailSuccess || waSuccess ? 'partial' : 'failed');
const lastAttemptAt = base.whatsapp_sent_at || base.email_sent_at || new Date().toISOString();

return { json: {
  'Lead ID': base.Email || base.lead_id || base.email_norm || '',
  'Email': base.Email || base.email_norm || '',
  'Full Name': base['Full Name'] || '',
  'Company': base.Company || '',
  'Phone': base.Phone || '',
  'Email Quality': base.email_quality || '',
  'Email Quality Reason': base.email_quality_reason || '',
  'Email Status': emailStatus,
  'Email Delivery Class': base.email_delivery_class || '',
  'Email SMTP Code': base.email_smtp_code || '',
  'Email Sent At': base.email_sent_at || '',
  'Email Message ID': base.email_message_id || '',
  'Email Error': base.email_error || '',
  'Email Delivery Note': base.email_delivery_note || '',
  'WhatsApp Status': waStatus,
  'WhatsApp Sent At': base.whatsapp_sent_at || '',
  'WhatsApp Message ID': base.whatsapp_message_id || '',
  'WhatsApp Error': base.whatsapp_error || '',
  'Outreach Status': outreach,
  'Last Attempt At': lastAttemptAt
} };

return {
  json: {
    ...$json,
    whatsapp_chat_id: $json.whatsappChatId || '',
    whatsapp_status: 'invalid_number',
    whatsapp_message_id: '',
    whatsapp_error: 'Phone number could not be normalized to a valid WhatsApp number',
    whatsapp_sent_at: ''
  }
};

return {
  json: {
    ...$json,
    whatsapp_chat_id: '',
    whatsapp_status: $json.whatsapp_enabled ? 'skipped_no_phone' : 'skipped_whatsapp_disabled',
    whatsapp_message_id: '',
    whatsapp_error: '',
    whatsapp_sent_at: ''
  }
};

return {
  json: {
    ...$json,
    email_status: 'invalid_email',
    email_message_id: '',
    email_error: 'Invalid or missing email address',
    email_sent_at: ''
  }
};

// Balanced Email Verification Gate
// This node validates what can be checked locally and trusts Apify only when it explicitly
// reports the address as verified/deliverable. It deliberately avoids aggressive heuristics:
// free-mail domains and name mismatches are NOT automatically rejected.

const email = String($json.email ?? '').trim().toLowerCase();
const sourceStatus = String($json.emailStatus ?? '').trim().toLowerCase();
const sourceVerified = String($json.emailVerified ?? '').trim().toLowerCase();

const DISPOSABLE = new Set([
  'mailinator.com','guerrillamail.com','guerrillamail.net','10minutemail.com',
  'tempmail.com','temp-mail.org','yopmail.com','getnada.com','sharklasers.com',
  'throwawaymail.com','emailondeck.com','dispostable.com','trashmail.com'
]);
const BLOCKED_LOCALS = new Set(['noreply','no-reply','mailer-daemon','postmaster','daemon']);
const ROLE_LOCALS = new Set([
  'info','contact','sales','support','admin','office','hello','hr','careers',
  'marketing','enquiries','inquiries','mail','team','billing','accounts','service',
  'customerservice','recruiting'
]);

const result = {
  ...$json,
  email,
  email_deliverability: {
    status: 'undeliverable',
    verified: false,
    source: 'apify-balanced-gate',
    reason: ''
  }
};

const fail = (reason) => {
  result.email_deliverability.reason = reason;
  result.email_verification_passed = false;
  return { json: result };
};

if (!email || email.length > 254 || !/^[A-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?(?:\.[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?)+$/i.test(email)) {
  return fail('invalid_email_format');
}

const parts = email.split('@');
if (parts.length !== 2) return fail('invalid_email_structure');
const local = parts[0];
const domain = parts[1];
if (local.length > 64) return fail('local_part_too_long');
if (DISPOSABLE.has(domain)) return fail('disposable_mail_domain');
if (BLOCKED_LOCALS.has(local)) return fail('non_delivery_mailbox');

// Apify remains the positive verification gate. We do not convert unknown/risky/etc. into valid.
const verifiedBySource = sourceStatus === 'deliverable' || sourceStatus === 'verified' || sourceVerified === 'true';
if (!verifiedBySource) {
  return fail(sourceStatus ? `source_status_${sourceStatus}` : 'source_verification_missing');
}

const companyDomain = String($json.companyDomain ?? '')
  .trim().toLowerCase()
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .split('/')[0];

const normalizeRoot = (d) => {
  const p = d.split('.').filter(Boolean);
  if (p.length >= 3 && ['co','com','org','net','gov','edu','ac'].includes(p[p.length - 2])) return p.slice(-3).join('.');
  return p.slice(-2).join('.');
};

// Only enforce domain consistency when the source actually provides a company domain.
if (companyDomain && normalizeRoot(domain) !== normalizeRoot(companyDomain)) {
  return fail('email_company_domain_mismatch');
}

const clean = (v) => String(v ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
const first = clean($json.firstName);
const last = clean($json.lastName);
const mailbox = clean(local);
const nameMatch = (first.length >= 3 && mailbox.includes(first)) || (last.length >= 3 && mailbox.includes(last));
const initialsMatch = first && last && mailbox.includes(first[0] + last[0]);
const roleMailbox = ROLE_LOCALS.has(local);
const freeMail = new Set(['gmail.com','googlemail.com','yahoo.com','ymail.com','hotmail.com','outlook.com','live.com','icloud.com','me.com','protonmail.com','proton.me','gmx.com','mail.com','zoho.com']).has(domain);

result.email_quality = roleMailbox ? 'review' : ((!nameMatch && !initialsMatch && (first || last)) ? 'review' : 'good');
result.email_quality_reason = roleMailbox
  ? 'verified_role_or_department_mailbox'
  : ((!nameMatch && !initialsMatch && (first || last)) ? 'verified_email_name_not_obvious_match' : 'verified_source_and_basic_checks_passed');
if (freeMail) result.email_quality_reason += ';free_mail_domain';

result.email_deliverability = {
  status: 'deliverable',
  verified: true,
  source: 'apify-balanced-gate',
  source_status: sourceStatus || 'verified',
  reason: 'verified_by_apify_and_passed_balanced_gate'
};
result.email_verification_passed = true;
result.email_domain = domain;
return { json: result };

// Balanced Email Quality Guard
// Goal: reject clearly bad records while preserving legitimate business emails that
// may look unusual. Apify's verified-email filter remains the primary verification layer.
const TARGET = new Set(['lebanon','united arab emirates','uae','saudi arabia','qatar','jordan']);
const DISPOSABLE = new Set([
  'mailinator.com','guerrillamail.com','guerrillamail.net','10minutemail.com',
  'tempmail.com','temp-mail.org','yopmail.com','getnada.com','sharklasers.com',
  'throwawaymail.com','emailondeck.com','dispostable.com','trashmail.com'
]);
const BLOCKED_LOCALS = new Set(['noreply','no-reply','mailer-daemon','postmaster','daemon']);
const ROLE_LOCALS = new Set([
  'info','contact','sales','support','admin','office','hello','hr','careers',
  'marketing','enquiries','inquiries','mail','team','billing','accounts','service',
  'customerservice','recruiting'
]);
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const norm = (v) => (v == null ? '' : String(v)).trim().toLowerCase();
const rootDomain = (d) => {
  const p = norm(d).replace(/^https?:\/\//,'').replace(/^www\./,'').split('/')[0].split('.').filter(Boolean);
  if (p.length >= 3 && ['co','com','org','net','gov','edu','ac'].includes(p[p.length - 2])) return p.slice(-3).join('.');
  return p.slice(-2).join('.');
};

const rows = $input.all().map(i => i.json || {});
const kept = [];
const reasons = {};
const bump = (r) => { reasons[r] = (reasons[r] || 0) + 1; };
let pulled = 0;
let apifyError = '';

for (const j of rows) {
  if (!Object.keys(j).length) continue;
  if (j.error && !j.email) {
    apifyError = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error));
    continue;
  }
  if (j.rowType && j.rowType !== 'lead') { bump('non_lead_row'); continue; }
  pulled++;

  const email = norm(j.email);
  if (!EMAIL_RE.test(email) || email.length > 254) { bump('invalid_email_format'); continue; }
  const [local, emailDomain] = email.split('@');
  if (!local || local.length > 64 || !emailDomain) { bump('invalid_email_structure'); continue; }
  if (DISPOSABLE.has(emailDomain)) { bump('disposable_domain'); continue; }
  if (BLOCKED_LOCALS.has(local)) { bump('non_delivery_mailbox'); continue; }

  const pc = norm(j.personCountry);
  const cc = norm(j.companyCountry);
  if (!(TARGET.has(pc) || (pc === '' && TARGET.has(cc)))) {
    bump('outside_target_markets');
    continue;
  }

  const companyDomain = norm(j.companyDomain);
  if (companyDomain && rootDomain(companyDomain) && rootDomain(companyDomain) !== rootDomain(emailDomain)) {
    bump('email_company_domain_mismatch');
    continue;
  }

  const first = norm(j.firstName).replace(/[^a-z0-9]/g, '');
  const last = norm(j.lastName).replace(/[^a-z0-9]/g, '');
  const mailbox = local.replace(/[^a-z0-9]/g, '');
  const nameMatch = (first.length >= 3 && mailbox.includes(first)) || (last.length >= 3 && mailbox.includes(last));
  const initialsMatch = first && last && mailbox.includes(first[0] + last[0]);
  const roleMailbox = ROLE_LOCALS.has(local);

  let emailQuality = 'good';
  let emailQualityReason = 'verified_source_and_basic_checks_passed';
  if (roleMailbox) {
    emailQuality = 'review';
    emailQualityReason = 'verified_role_or_department_mailbox';
  } else if (!nameMatch && !initialsMatch && (first || last)) {
    emailQuality = 'review';
    emailQualityReason = 'verified_email_name_not_obvious_match';
  }

  let company = String(j.companyName || '').trim();
  const fullName = `${j.firstName || ''}${j.lastName || ''}`.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (company && company.toLowerCase().replace(/[^a-z0-9]/g, '') === fullName) company = '';

  kept.push({ json: {
    ...j,
    email,
    companyName: company,
    email_quality: emailQuality,
    email_quality_reason: emailQualityReason
  }});
}

const passedCount = kept.length;
const rejected = Math.max(0, pulled - passedCount);
const status = apifyError
  ? 'APIFY ERROR: ' + apifyError
  : (pulled === 0 ? 'NO LEADS RETURNED - search pool may be exhausted' : (passedCount === 0 ? 'ALL LEADS REJECTED BY QUALITY GUARD' : 'OK'));

kept.push({ json: {
  _runStats: true,
  'Run Time': new Date().toISOString(),
  'Pulled': pulled,
  'Passed Quality Guard': passedCount,
  'Rejected': rejected,
  'Rejection Reasons': Object.entries(reasons).map(([k,v]) => `${k}:${v}`).join('; '),
  'Status': status
}});
return kept;

const ctx = $('Prepare Outreach Context').item.json;
return {
  json: {
    ...ctx,
    email_status: 'email_skipped_no_copy',
    email_message_id: '',
    email_error: 'AI email copy was empty or failed - email not sent',
    email_sent_at: ''
  }
};

// Distinguish a genuine 'not registered' response from a Green-API check failure.
let ctx = {};
try { ctx = $('Code in JavaScript').item.json || {}; } catch (e) {}
const resp = $json || {};
const checkFailed = !!resp.error;
const errText = checkFailed ? ((resp.error && resp.error.message) ? resp.error.message : String(resp.error)) : '';
return { json: {
  ...ctx,
  whatsapp_chat_id: ctx.whatsappChatId || '',
  whatsapp_status: checkFailed ? 'whatsapp_check_failed' : 'whatsapp_not_registered',
  whatsapp_message_id: '',
  whatsapp_error: checkFailed ? errText : 'Green-API reports that this phone number is not registered on WhatsApp',
  whatsapp_sent_at: '',
  whatsapp_check_response: resp
} };
